public interface Expression { int interpret(Context ctx); }
public final class Number implements Expression {
    private final int value;
    public Number(int value) { this.value = value; }
    public int interpret(Context ctx) { return value; }
}
public final class Add implements Expression {
    private final Expression left, right;
    public Add(Expression l, Expression r) { this.left = l; this.right = r; }
    public int interpret(Context ctx) {
        return left.interpret(ctx) + right.interpret(ctx);
    }
}
